5	namespace PhpAiToolkit\PhpStan\Rule\ForbidClassLikeNameSuffix;
6	
7	/**
8	 * Finds configured forbidden suffixes on class-like names.
9	 */
10	final class ForbiddenClassLikeSuffixes
11	{
12	    /** @var list<string> */
13	    private array $suffixes;
14	
15	    /**
16	     * @param list<string> $suffixes configured forbidden suffixes
17	     */
18	    public function __construct(array $suffixes)
19	    {
20	        $this->suffixes = array_values(array_unique(array_filter(
21	            $suffixes,
22	            static fn (string $suffix): bool => $suffix !== '',
23	        )));
24	    }
25	
26	    /**
27	     * Returns the matching forbidden suffix for a class-like name.
28	     */
29	    public function matchingSuffix(string $name): ?string
30	    {
31	        foreach ($this->suffixes as $suffix) {
32	            if (str_ends_with($name, $suffix)) {
33	                return $suffix;
34	            }
35	        }
36	
37	        return null;
38	    }
39	}
