5	namespace PhpAiToolkit\PhpStan\Rule\Shared;
6	
7	use PhpAiToolkit\PhpStan\Rule\ForbiddenCommentRule;
8	
9	/**
10	 * Detects suppression comments handled by ForbiddenCommentRule.
11	 */
12	final class ForbiddenCommentPattern
13	{
14	    private const PHPSTAN_IGNORE_PATTERN = '/@phpstan-ignore(?:-line|-next-line)?\b/';
15	    private const INFECTION_IGNORE_ALL_PATTERN = '/@infection-ignore-all\b/';
16	
17	    /**
18	     * Reports whether the text contains a PHPStan ignore directive.
19	     */
20	    public function isPhpstanIgnore(string $text): bool
21	    {
22	        return preg_match(self::PHPSTAN_IGNORE_PATTERN, $text) === 1;
23	    }
24	
25	    /**
26	     * Reports whether the text contains an Infection ignore-all directive.
27	     */
28	    public function isInfectionIgnoreAll(string $text): bool
29	    {
30	        return preg_match(self::INFECTION_IGNORE_ALL_PATTERN, $text) === 1;
31	    }
32	
33	    /**
34	     * Reports whether the comment is already handled by ForbiddenCommentRule.
35	     */
36	    public function isHandled(string $text): bool
37	    {
38	        return $this->isPhpstanIgnore($text) || $this->isInfectionIgnoreAll($text);
39	    }
40	
41	    /**
42	     * Returns the line PHPStan associates with an ignore comment.
43	     */
44	    public function reportedLine(string $text, int $line): int
45	    {
46	        if (str_contains($text, '@phpstan-ignore-line')) {
47	            return $line + 1;
48	        }
49	
50	        return $line;
51	    }
52	}
